27	BlockIO InterpreterRenameQuery::execute()
28	{
29	    const auto & rename = query_ptr->as<const ASTRenameQuery &>();
30	
31	    if (!rename.cluster.empty())
32	    {
33	        DDLQueryOnClusterParams params;
34	        params.access_to_check = getRequiredAccess();
35	        return executeDDLQueryOnCluster(query_ptr, getContext(), params);
36	    }
37	
38	    getContext()->checkAccess(getRequiredAccess());
39	
40	    String path = getContext()->getPath();
41	    String current_database = getContext()->getCurrentDatabase();
42	
43	    /** In case of error while renaming, it is possible that only part of tables was renamed
44	      *  or we will be in inconsistent state. (It is worth to be fixed.)
45	      */
46	
47	    RenameDescriptions descriptions;
48	    descriptions.reserve(rename.elements.size());
49	
50	    /// Don't allow to drop tables (that we are renaming); don't allow to create tables in places where tables will be renamed.
51	    TableGuards table_guards;
52	
53	    for (const auto & elem : rename.elements)
54	    {
55	        descriptions.emplace_back(elem, current_database);
56	        const auto & description = descriptions.back();
57	
58	        UniqueTableName from(description.from_database_name, description.from_table_name);
59	        UniqueTableName to(description.to_database_name, description.to_table_name);
60	
61	        table_guards[from];
62	        table_guards[to];
63	    }
64	
65	    auto & database_catalog = DatabaseCatalog::instance();
66	
67	    /// Must do it in consistent order.
68	    for (auto & table_guard : table_guards)
69	        table_guard.second = database_catalog.getDDLGuard(table_guard.first.database_name, table_guard.first.table_name);
70	
71	    if (rename.database)
72	        return executeToDatabase(rename, descriptions);
73	    else
74	        return executeToTables(rename, descriptions, table_guards);
75	}
