77	BlockIO InterpreterRenameQuery::executeToTables(const ASTRenameQuery & rename, const RenameDescriptions & descriptions, TableGuards & ddl_guards)
78	{
79	    assert(!rename.rename_if_cannot_exchange || descriptions.size() == 1);
80	    assert(!(rename.rename_if_cannot_exchange && rename.exchange));
81	    auto & database_catalog = DatabaseCatalog::instance();
82	
83	    for (const auto & elem : descriptions)
84	    {
85	        if (elem.if_exists)
86	        {
87	            assert(!rename.exchange);
88	            if (!database_catalog.isTableExist(StorageID(elem.from_database_name, elem.from_table_name), getContext()))
89	                continue;
90	        }
91	
92	        bool exchange_tables;
93	        if (rename.exchange)
94	        {
95	            exchange_tables = true;
96	        }
97	        else if (rename.rename_if_cannot_exchange)
98	        {
99	            exchange_tables = database_catalog.isTableExist(StorageID(elem.to_database_name, elem.to_table_name), getContext());
100	            renamed_instead_of_exchange = !exchange_tables;
101	        }
102	        else
103	        {
104	            exchange_tables = false;
105	            database_catalog.assertTableDoesntExist(StorageID(elem.to_database_name, elem.to_table_name), getContext());
106	        }
107	
108	        DatabasePtr database = database_catalog.getDatabase(elem.from_database_name);
109	        if (typeid_cast<DatabaseReplicated *>(database.get()) && !getContext()->getClientInfo().is_replicated_database_internal)
110	        {
111	            if (1 < descriptions.size())
112	                throw Exception(
113	                    ErrorCodes::NOT_IMPLEMENTED,
114	                    "Database {} is Replicated, "
115	                    "it does not support renaming of multiple tables in single query.",
116	                    elem.from_database_name);
117	
118	            UniqueTableName from(elem.from_database_name, elem.from_table_name);
119	            UniqueTableName to(elem.to_database_name, elem.to_table_name);
120	            ddl_guards[from]->releaseTableLock();
121	            ddl_guards[to]->releaseTableLock();
122	            return typeid_cast<DatabaseReplicated *>(database.get())->tryEnqueueReplicatedDDL(query_ptr, getContext());
123	        }
124	        else
125	        {
126	            TableNamesSet dependencies;
127	            if (!exchange_tables)
128	                dependencies = database_catalog.tryRemoveLoadingDependencies(StorageID(elem.from_database_name, elem.from_table_name),
129	                                                                             getContext()->getSettingsRef().check_table_dependencies);
130	
131	            database->renameTable(
132	                getContext(),
133	                elem.from_table_name,
134	                *database_catalog.getDatabase(elem.to_database_name),
135	                elem.to_table_name,
136	                exchange_tables,
137	                rename.dictionary);
138	
139	            if (!dependencies.empty())
140	                DatabaseCatalog::instance().addLoadingDependencies(QualifiedTableName{elem.to_database_name, elem.to_table_name}, std::move(dependencies));
141	        }
142	    }
143	
144	    return {};
145	}
