147	BlockIO InterpreterRenameQuery::executeToDatabase(const ASTRenameQuery &, const RenameDescriptions & descriptions)
148	{
149	    assert(descriptions.size() == 1);
150	    assert(descriptions.front().from_table_name.empty());
151	    assert(descriptions.front().to_table_name.empty());
152	
153	    const auto & old_name = descriptions.front().from_database_name;
154	    const auto & new_name = descriptions.back().to_database_name;
155	    auto & catalog = DatabaseCatalog::instance();
156	
157	    auto db = descriptions.front().if_exists ? catalog.tryGetDatabase(old_name) : catalog.getDatabase(old_name);
158	
159	    if (db)
160	    {
161	        catalog.assertDatabaseDoesntExist(new_name);
162	        db->renameDatabase(getContext(), new_name);
163	    }
164	
165	    return {};
166	}
