168	AccessRightsElements InterpreterRenameQuery::getRequiredAccess() const
169	{
170	    AccessRightsElements required_access;
171	    const auto & rename = query_ptr->as<const ASTRenameQuery &>();
172	    for (const auto & elem : rename.elements)
173	    {
174	        required_access.emplace_back(AccessType::SELECT | AccessType::DROP_TABLE, elem.from.database, elem.from.table);
175	        required_access.emplace_back(AccessType::CREATE_TABLE | AccessType::INSERT, elem.to.database, elem.to.table);
176	        if (rename.exchange)
177	        {
178	            required_access.emplace_back(AccessType::CREATE_TABLE | AccessType::INSERT, elem.from.database, elem.from.table);
179	            required_access.emplace_back(AccessType::SELECT | AccessType::DROP_TABLE, elem.to.database, elem.to.table);
180	        }
181	    }
182	    return required_access;
183	}
