185	void InterpreterRenameQuery::extendQueryLogElemImpl(QueryLogElement & elem, const ASTPtr & ast, ContextPtr) const
186	{
187	    elem.query_kind = "Rename";
188	    const auto & rename = ast->as<const ASTRenameQuery &>();
189	    for (const auto & element : rename.elements)
190	    {
191	        {
192	            String database = backQuoteIfNeed(element.from.database.empty() ? getContext()->getCurrentDatabase() : element.from.database);
193	            elem.query_databases.insert(database);
194	            elem.query_tables.insert(database + "." + backQuoteIfNeed(element.from.table));
195	        }
196	        {
197	            String database = backQuoteIfNeed(element.to.database.empty() ? getContext()->getCurrentDatabase() : element.to.database);
198	            elem.query_databases.insert(database);
199	            elem.query_tables.insert(database + "." + backQuoteIfNeed(element.to.table));
200	        }
201	    }
202	}
