13	/// To avoid deadlocks, we must acquire locks for tables in same order in any different RENAMES.
14	struct UniqueTableName
15	{
16	    String database_name;
17	    String table_name;
18	
19	    UniqueTableName(const String & database_name_, const String & table_name_)
20	            : database_name(database_name_), table_name(table_name_) {}
21	
22	    bool operator< (const UniqueTableName & rhs) const
23	    {
24	        return std::tie(database_name, table_name) < std::tie(rhs.database_name, rhs.table_name);
25	    }
26	};
