28	struct RenameDescription
29	{
30	    RenameDescription(const ASTRenameQuery::Element & elem, const String & current_database) :
31	            from_database_name(elem.from.database.empty() ? current_database : elem.from.database),
32	            from_table_name(elem.from.table),
33	            to_database_name(elem.to.database.empty() ? current_database : elem.to.database),
34	            to_table_name(elem.to.table),
35	            if_exists(elem.if_exists)
36	    {}
37	
38	    String from_database_name;
39	    String from_table_name;
40	
41	    String to_database_name;
42	    String to_table_name;
43	    bool if_exists;
44	};
